import { createReadStream, existsSync, mkdirSync, promises as fs } from 'node:fs';
import { dirname, join, normalize, resolve, sep } from 'node:path';
import type { Readable } from 'node:stream';
import type { StorageDriver, StoredObject } from './storage.types';

// Development / single-node driver. Keys are generated by the storage service;
// this driver still re-validates every resolved path so a malformed key can
// never escape the configured root.
export class LocalStorageDriver implements StorageDriver {
  readonly name = 'local';
  private readonly root: string;

  constructor(rootPath: string) {
    this.root = resolve(rootPath);
  }

  private resolveKey(key: string): string {
    const normalized = normalize(key);
    if (normalized.startsWith('..') || normalized.includes(`..${sep}`)) {
      throw new Error('storage.key_traversal');
    }
    const target = resolve(join(this.root, normalized));
    if (!target.startsWith(this.root)) {
      throw new Error('storage.key_outside_root');
    }
    return target;
  }

  async put(key: string, body: Buffer, _contentType: string): Promise<StoredObject> {
    const target = this.resolveKey(key);
    mkdirSync(dirname(target), { recursive: true });
    await fs.writeFile(target, body, { mode: 0o640 });
    return { key, sizeBytes: body.byteLength };
  }

  async get(key: string): Promise<Buffer> {
    return fs.readFile(this.resolveKey(key));
  }

  createReadStream(key: string): Readable {
    return createReadStream(this.resolveKey(key));
  }

  async exists(key: string): Promise<boolean> {
    return existsSync(this.resolveKey(key));
  }

  async delete(key: string): Promise<void> {
    try {
      await fs.unlink(this.resolveKey(key));
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      // Deleting an object that is already gone is a success (idempotent).
      if (code !== 'ENOENT') throw error;
    }
  }
}
